import { useQuery } from "@tanstack/react-query";
import type { Army } from "shared/schemas/army";
import type { CO } from "shared/schemas/co";
import type { UnitType } from "shared/schemas/unit";

/** Generated by utils/import-commander-wars/import.py */
export const assetsPath = "/commander-wars/";

export type SpriteStrip = { src: string; frames: number };

export type ArmyBattleSprites = {
  idle: SpriteStrip | null;
  /** the middle of the body in the idle sprite, from its bottom left */
  center: [number, number];
  fire: SpriteStrip | null;
  move: SpriteStrip | null;
  stop: SpriteStrip | null;
  dying: SpriteStrip | null;
  /** pieces drawn on top of the unit, that only move when it fires */
  parts: (SpriteStrip & { offset: [number, number] })[];
};

export type UnitBattleData = {
  kind: "foot" | "land" | "air" | "copter" | "sea";
  maxCount: number;
  fireMs: number;
  fireSounds: string[];
  /** where the unit stands, from the bottom left of its side */
  position: [number, number];
  flash: SpriteStrip | null;
  /** where the shot starts, from the formation point and not from the unit */
  flashOffset: [number, number] | null;
  /** how far the shot flies: x, y, milliseconds. Null if it stays in place. */
  flashTravel: [number, number, number] | null;
  impact: SpriteStrip | null;
  impactSounds: string[];
  armies: Record<Army, ArmyBattleSprites>;
};

export type BattleManifest = {
  units: Record<UnitType, UnitBattleData>;
  cos: Partial<Record<CO, { face?: string; full?: string; music?: string }>>;
  explosions: { land: SpriteStrip; air: SpriteStrip };
};

export const assetUrl = (path: string) =>
  assetsPath + path.split("/").map(encodeURIComponent).join("/");

let manifest: Promise<BattleManifest> | undefined;

export const loadBattleManifest = () => {
  manifest ??= fetch(`${assetsPath}battle-manifest.json`).then(
    (response) => response.json() as Promise<BattleManifest>,
  );

  return manifest;
};

export const useBattleManifest = () =>
  useQuery({
    queryKey: ["battle-manifest"],
    queryFn: loadBattleManifest,
    staleTime: Infinity,
  }).data;
